@classmethod
def _validate_replay_positions(
    cls,
    replay: Sequence[Mapping[str, object]],
    tick: int,
    robot_by_id: Mapping[str, Robot],
    base_grid: GridMap,
    changes: Sequence[Mapping[str, object]] = (),
) -> None:
    """Reject history that the simulator could never have produced.

    Every tick frame is checked against the map in effect at that moment:
    positions must be in bounds and traversable, no two robots may share a
    cell, each robot may only wait or step one orthogonal cell between
    consecutive tick frames (two robots may not swap cells within a tick),
    and ``moved`` must list exactly the robots whose positions changed.

    Version 2 map changes take effect after the tick they are stamped on,
    in their recorded order. A robot on a tick frame at tick *t* sees the
    map obtained by applying every change stamped ``<= t``; changes stamped
    ``0`` apply before the first tick frame. A change may never add an
    obstacle onto a cell occupied by a recorded tick frame, even when a
    later change in the same tick removes it again. Adjacency is checked
    between tick frames only -- intervening map changes never move robots.

    Version 1 files have no map changes, so the saved (base) grid applies
    throughout. The very first frame has no predecessor frame: its cells,
    overlaps and ``moved`` ids are still checked, but nothing is inferred
    about the (unrecorded) initial positions.
    """
    tick_frames = [frame for frame in replay if frame.get("type") == "tick"]
    if len(tick_frames) != tick:
        raise ValueError(
            f"replay has {len(tick_frames)} tick frames but the checkpoint is at tick {tick}"
        )

    expected_ids = set(robot_by_id)

    def frame_positions(frame: Mapping[str, object]) -> dict[str, tuple[int, int]]:
        raw = frame["robots"]
        assert isinstance(raw, dict)
        if set(raw) != expected_ids:
            raise ValueError(
                f"replay frame {frame['tick']} robot ids do not match current robots"
            )
        return {robot_id: tuple(position) for robot_id, position in raw.items()}

    # Grid state as map changes take effect. Version 1 passes no changes,
    # so the saved grid governs every frame.
    obstacles = set(base_grid.obstacles)
    width, height = base_grid.width, base_grid.height
    change_index = 0
    applied_until_tick = 0

    def grid_for_tick(frame_tick: int) -> GridMap:
        nonlocal change_index, applied_until_tick
        # Changes take effect once the tick they are stamped on has ended,
        # so frame t sees every change with a stamp <= t; tick-0 changes
        # predate the first frame.
        while change_index < len(changes) and changes[change_index]["tick"] <= frame_tick:
            change = changes[change_index]
            sequence = change["sequence"]
            added = {tuple(cell) for cell in change["added"]}
            removed = {tuple(cell) for cell in change["removed"]}
            # Robots occupy this grid while the tick they were recorded in
            # has already ended, so a newly added obstacle would trap one.
            for cell in added:
                if cell in occupied_after_tick.get(applied_until_tick, {}):
                    raise ValueError(
                        f"map change {sequence} (after tick {change['tick']}) adds "
                        f"obstacle {list(cell)} occupied by a robot in tick frame "
                        f"{applied_until_tick}"
                    )
            obstacles.update(added)
            obstacles.difference_update(removed)
            change_index += 1
            applied_until_tick = change["tick"]
        return GridMap(width, height, frozenset(obstacles))

    previous: dict[str, tuple[int, int]] | None = None
    # Robot positions recorded at the tick that has just ended, keyed by
    # tick number; consumed when the following changes are applied.
    occupied_after_tick: dict[int, dict[str, tuple[int, int]]] = {}
    for frame in tick_frames:
        frame_tick = frame["tick"]
        positions = frame_positions(frame)
        grid = grid_for_tick(frame_tick)

        for robot_id, position in positions.items():
            if not grid.contains(position):
                raise ValueError(
                    f"replay frame {frame_tick} robot {robot_id!r} is at "
                    f"{list(position)}, outside the map in effect at tick {frame_tick}"
                )
            if position in grid.obstacles:
                raise ValueError(
                    f"replay frame {frame_tick} robot {robot_id!r} is at "
                    f"{list(position)}, an obstacle on the map in effect at tick "
                    f"{frame_tick}"
                )

        seen_cells: dict[tuple[int, int], str] = {}
        for robot_id, position in positions.items():
            occupant = seen_cells.get(position)
            if occupant is not None:
                raise ValueError(
                    f"replay frame {frame_tick} robots {occupant!r} and {robot_id!r} "
                    f"both occupy {list(position)}"
                )
            seen_cells[position] = robot_id

        moved = frame["moved"]
        assert isinstance(moved, list)
        moved_seen: set[str] = set()
        for robot_id in moved:
            if robot_id not in expected_ids:
                raise ValueError(
                    f"replay frame {frame_tick} 'moved' lists unknown robot {robot_id!r}"
                )
            if robot_id in moved_seen:
                raise ValueError(
                    f"replay frame {frame_tick} 'moved' lists robot {robot_id!r} more "
                    "than once"
                )
            moved_seen.add(robot_id)

        if previous is not None:
            actually_moved: set[str] = set()
            for robot_id, position in positions.items():
                old = previous[robot_id]
                distance = abs(position[0] - old[0]) + abs(position[1] - old[1])
                if distance > 1:
                    raise ValueError(
                        f"replay frame {frame_tick} robot {robot_id!r} jumps "
                        f"{distance} cells from {list(old)} to {list(position)}"
                    )
                if distance == 1:
                    actually_moved.add(robot_id)
            # Swapping two adjacent cells within one tick is impossible even
            # though every individual step is only one cell.
            for robot_id, position in positions.items():
                other = previous[robot_id]
                if position != other and previous[next(iter(()))] if False else False:
                    pass
            movers = {
                robot_id: (previous[robot_id], positions[robot_id])
                for robot_id in actually_moved
            }
            for robot_id, (old, new) in movers.items():
                for other_id, (other_old, other_new) in movers.items():
                    if other_id < robot_id and old == other_new and new == other_old:
                        raise ValueError(
                            f"replay frame {frame_tick} robots {other_id!r} and "
                            f"{robot_id!r} swap cells {list(old)} and {list(new)} "
                            "within one tick"
                        )
            if moved_seen != actually_moved:
                missing = sorted(actually_moved - moved_seen)
                extra = sorted(moved_seen - actually_moved)
                details = []
                if missing:
                    details.append(f"missing movers {missing}")
                if extra:
                    details.append(f"non-moving robots listed {extra}")
                raise ValueError(
                    f"replay frame {frame_tick} 'moved' does not match the robots "
                    f"that changed position ({'; '.join(details)})"
                )

        occupied_after_tick = {frame_tick: positions}
        # Let any changes stamped with this tick see the frame's occupants.
        previous = positions
        applied_until_tick = frame_tick

    # Changes stamped after the final recorded tick still must be applied to
    # reproduce the saved grid, and are validated against the last frame.
    while change_index < len(changes):
        change = changes[change_index]
        sequence = change["sequence"]
        added = {tuple(cell) for cell in change["added"]}
        stamp = change["tick"]
        occupants = tick_frames[-1]["robots"] if tick_frames else {}
        assert isinstance(occupants, dict)
        for cell in added:
            for robot_id, position in occupants.items():
                if tuple(position) == cell and stamp == tick:
                    raise ValueError(
                        f"map change {sequence} (after tick {stamp}) adds obstacle "
                        f"{list(cell)} occupied by robot {robot_id!r} in the final "
                        "tick frame"
                    )
        obstacles.update(added)
        obstacles.difference_update({tuple(cell) for cell in change["removed"]})
        change_index += 1

    if tick > 0:
        last_positions = frame_positions(tick_frames[-1])
        for robot_id, position in last_positions.items():
            if position != robot_by_id[robot_id].position:
                raise ValueError(
                    "last replay frame positions do not match current robot positions "
                    f"for robot {robot_id!r}"
                )

